3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.util.Sha256;
6	
7	/**
8	 * Canonical key identifying a household by its owner's last name and postcode. Two owners
9	 * belong to the same household when their keys are equal: the last name is normalized
10	 * (leading/trailing and repeated whitespace collapsed to a single space, then lower-cased) so
11	 * incidental formatting differences do not hide a match, while the postcode is taken verbatim.
12	 */
13	final class HouseholdKey {
14	
15	    /** Number of leading hex characters of the digest kept as the household id. */
16	    private static final int ID_LENGTH = 12;
17	
18	    private HouseholdKey() {
19	    }
20	
21	    static String of(String lastName, String postcode) {
22	        return normalize(lastName) + '|' + (postcode == null ? "" : postcode);
23	    }
24	
25	    /**
26	     * Stable identifier shared by every owner of a household: the first {@value #ID_LENGTH} hex
27	     * characters of the SHA-256 digest of the canonical {@link #of(String, String) key}. Purely
28	     * derived from last name and postcode, so two owners in the same household always get the same
29	     * value regardless of creation order.
30	     */
31	    static String id(String lastName, String postcode) {
32	        return Sha256.hex(of(lastName, postcode)).substring(0, ID_LENGTH);
33	    }
34	
35	    private static String normalize(String value) {
36	        if (value == null) {
37	            return "";
38	        }
39	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
40	    }
41	}
