10	/**
11	 * Caps a new owner's membership level at one above the highest membership level among their
12	 * existing household members — those sharing its {@link HouseholdKey household id}. Runs after
13	 * {@link AssignHouseholdId} has set the id and before {@link SaveOwner} persists the entity, so
14	 * {@code findAll()} sees only the owners that existed before this create. When the household has
15	 * no existing member, no cap applies and the level is left uncapped. The cap is stored on the
16	 * owner so every later read derives the same capped level.
17	 */
18	public class CapMembershipLevel {
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        String householdId = owner.getHouseholdId();
22	        LocalDate asOf = LocalDate.now();
23	        Integer maxLevel = null;
24	        for (Owner existing : ownerRepository.findAll()) {
25	            if (existing.isDeleted()) {
26	                continue; // a soft-deleted owner is no longer a household member
27	            }
28	            if (householdId.equals(existing.getHouseholdId())) {
29	                int level = MembershipLevels.levelOf(existing, asOf);
30	                if (maxLevel == null || level > maxLevel) {
31	                    maxLevel = level;
32	                }
33	            }
34	        }
35	        if (maxLevel != null) {
36	            owner.setMembershipLevelCap(maxLevel + 1);
37	        }
38	    }
39	}
