13	
14	    private Sha256() {
15	    }
16	
17	    /** The lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}. */
18	    public static String hex(String value) {
19	        byte[] digest;
20	        try {
21	            digest = MessageDigest.getInstance("SHA-256")
22	                    .digest(value.getBytes(StandardCharsets.UTF_8));
23	        }
24	        catch (NoSuchAlgorithmException ex) {
25	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
26	        }
27	        StringBuilder hex = new StringBuilder(digest.length * 2);
28	        for (byte b : digest) {
29	            hex.append(Character.forDigit((b >> 4) & 0xF, 16));
30	            hex.append(Character.forDigit(b & 0xF, 16));
31	        }
32	        return hex.toString();
33	    }
34	}
