3	/**
4	 * Shared telephone normalization to E.164 form. Strips spaces, dashes and brackets, then:
5	 * keeps a leading '+' and country code when present; otherwise assumes country code '+61'
6	 * and drops a single leading '0' from the national digits. The result must carry 8 to 15
7	 * digits after the '+'. Used both to canonicalize an incoming request's telephone and to
8	 * compare it against the telephones already stored on other owners.
9	 */
10	final class TelephoneNormalizer {
11	
12	    private TelephoneNormalizer() {
13	    }
14	
15	    /**
16	     * Returns the E.164 representation of {@code raw} (a leading '+' followed by 8-15
17	     * digits), or {@code null} when it cannot form a valid E.164 number.
18	     */
19	    static String toE164(String raw) {
20	        if (raw == null) {
21	            return null;
22	        }
23	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
24	        String digits;
25	        if (cleaned.startsWith("+")) {
26	            digits = cleaned.substring(1);
27	        } else {
28	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
29	            digits = "61" + national;
30	        }
31	        if (!digits.matches("[0-9]{8,15}")) {
32	            return null;
33	        }
34	        return "+" + digits;
35	    }
36	}
